<script setup>
import {computed} from 'vue'
import {useRoom} from '../stores/room'
import {roomItemMap} from '../data/roomItems'
const room=useRoom(),objects=computed(()=>room.design.placements.map(p=>({...p,item:roomItemMap[room.inventory.find(i=>i.id===p.copyId)?.item_id]})).filter(p=>p.item))
const style=computed(()=>({backgroundColor:room.design.wall,backgroundImage:(room.design.grid?'linear-gradient(#91a5bb22 1px,transparent 1px),linear-gradient(90deg,#91a5bb22 1px,transparent 1px),':'')+`linear-gradient(to bottom,${room.design.wall} 0 76%,${room.design.floor} 76% 100%)`,backgroundSize:room.design.grid?'24px 24px,24px 24px,100% 100%':'100% 100%'}))
function selectPlaced(e,p){if(room.selected&&!room.selectedPlacement)return;e.stopPropagation();room.selected=p.copyId}
function place(e){if(!room.editing||!room.selected||room.busy)return;const box=e.currentTarget.getBoundingClientRect();room.place(Math.max(0,Math.min(100,(e.clientX-box.left)/box.width*100)),Math.max(0,Math.min(100,(e.clientY-box.top)/box.height*100)))}
</script>
<template><div :class="['room-scene',{editing:room.editing}]" :style="style" role="group" aria-label="포켓몬 방 배치 공간" @click="place"><div v-for="front in [false,true]" :key="String(front)" :class="['room-objects',{front}]" ><span v-for="p in objects.filter(p=>p.front===front)" :key="p.copyId" :class="['room-object',{selected:room.editing&&room.selected===p.copyId,front:p.front}]" :style="{left:p.x+'%',top:p.y+'%',fontSize:p.size+'cqw',transform:'translate(-50%,-50%) rotate('+p.rotation+'deg)'}"><button v-if="room.editing" type="button" :aria-label="p.item.name+' 배치 선택'" :disabled="room.busy" @click="selectPlaced($event,p)">{{p.item.emoji}}</button><span v-else aria-hidden="true">{{p.item.emoji}}</span></span></div><div class="room-pet"><slot/></div><span v-if="room.editing" class="room-edit-hint">{{room.selectedItem?room.selectedItem.name+' · 놓을 곳을 클릭하세요':'내 아이템에서 방 장식을 선택하세요'}}</span></div></template>
<style scoped>
.room-scene{position:relative;isolation:isolate;container-type:inline-size;overflow:visible}.room-pet{display:contents}.room-objects{position:absolute;inset:0;overflow:hidden;z-index:1;pointer-events:none}.room-objects.front{z-index:5}.room-object{position:absolute;z-index:1;line-height:1;pointer-events:none;font-family:'Segoe UI Emoji','Apple Color Emoji',sans-serif;max-width:none}.room-object.front{z-index:5}.room-object button{all:unset;cursor:pointer;pointer-events:auto;font:inherit;display:block;line-height:1;touch-action:manipulation}.room-object.selected{outline:2px dashed var(--rpg-edge);outline-offset:4px}.room-scene.editing{cursor:crosshair}.room-scene.editing .room-pet{pointer-events:none}.room-edit-hint{position:absolute;bottom:3px;left:50%;transform:translateX(-50%);background:var(--rpg-paper);color:var(--rpg-ink);border:1px solid var(--rpg-edge);padding:3px 8px;font-size:10px;z-index:8;pointer-events:none;white-space:nowrap;max-width:95%;overflow:hidden;text-overflow:ellipsis}.room-pet :deep(.dressed-partner){z-index:3}.room-pet :deep(.care-heart-burst){z-index:7}
</style>
